WHISKER_MAX = 3.0
WHISKER_SAFE_DISTANCE = 0.5
MAX_FORCE = 50.0
PHASE_NAVIGATE = "NAVIGATE"
PHASE_UNLOCK = "UNLOCK"
PHASE_ESCAPE = "ESCAPE"
PHASE_HOLD = "HOLD"

class Memory:
    def __init__(self):
        self.data = {}
    def clear(self):
        self.data = {}

MEM = Memory()

def build_agent(sandbox):
    MEM.clear()
    return sandbox.get_agent_body()

def agent_action(sandbox, agent_body, step_count):
    pd = sandbox.get_agent_position()
    x, y = pd
    front, up, down = sandbox.get_whisker_readings()
    vx, vy = sandbox.get_agent_velocity()
    speed = math.hypot(vx, vy)

    if "initial_state" not in MEM.data:
        MEM.data["initial_state"] = {
            "phase": PHASE_NAVIGATE,
            "unlock_counter": 0,
            "last_x": x,
            "last_y": y,
        }
    state = MEM.data["initial_state"]

    state["last_x"], state["last_y"] = x, y

    if state["phase"] == PHASE_NAVIGATE:
        fx = MAX_FORCE
        fy = 0.0

        if front < WHISKER_MAX - WHISKER_SAFE_DISTANCE:
            # Apply lateral force to avoid front wall
            fx = 0.0
            fy = MAX_FORCE
        elif down < WHISKER_SAFE_DISTANCE:
            # Apply upward force
            fy = MAX_FORCE
        elif up < WHISKER_SAFE_DISTANCE:
            # Apply downward force
            fy = -MAX_FORCE
        else:
            # Move forward
            fx = MAX_FORCE

        if ACTIVATION_X_MIN <= x <= ACTIVATION_X_MAX:
            state["phase"] = PHASE_UNLOCK
            state["unlock_counter"] = 0
        else:
            sandbox.apply_agent_force(fx, fy)
    elif state["phase"] == PHASE_UNLOCK:
        fx = BACKWARD_FX_THRESHOLD - 1.0  # Just below threshold
        fy = 0.0

        if (ACTIVATION_X_MIN <= x <= ACTIVATION_X_MAX and 
            fx < BACKWARD_FX_THRESHOLD and 
            speed < BACKWARD_SPEED_MAX):
            state["unlock_counter"] += 1
            if state["unlock_counter"] >= 5:
                state["phase"] = PHASE_ESCAPE
                state["unlock_counter"] = 0
        else:
            state["unlock_counter"] = 0

        sandbox.apply_agent_force(fx, fy)
    elif state["phase"] == PHASE_ESCAPE:
        fx = MAX_FORCE
        fy = 0.0

        if x >= EXIT_X_MIN and 0.5 <= y <= 2.5:
            state["phase"] = PHASE_HOLD
        else:
            sandbox.apply_agent_force(fx, fy)
    elif state["phase"] == PHASE_HOLD:
        fx = 0.0
        fy = 0.0
        sandbox.apply_agent_force(fx, fy)

